class Fees {
    // 만 원 이상은 무료이고 음수 금액은 거절해요.
    static int shipping(int amount) {
        if (amount < 0) throw new IllegalArgumentException("negative");
        return amount >= 10000 ? 0 : 2000;
    }
}

public class Main {
    public static void main(String[] args) {
        // 준비: 요구에서 금액과 기대값을 정해요.
        int amount = 9999;
        int expected = 2000;
        // 행동: 실제 구현을 호출해요.
        int actual = Fees.shipping(amount);
        // 확인: 기대와 다르면 검사 실패예요.
        if (actual != expected) throw new AssertionError("fee");
        System.out.println("ok");
    }
}

