class Counter {
    // 같은 객체를 다시 쓰면 이전 상태도 이어져요.
    int count;
    int next() { return ++count; }
}

public class Main {
    public static void main(String[] args) {
        Counter shared = new Counter();
        System.out.println(shared.next());
        System.out.println(shared.next());
        // 독립된 사례는 필요한 초기 상태로 시작해요.
        System.out.println(new Counter().next());
    }
}

